import zeros = require( '@stdlib/ndarray/zeros' );
import snrm2 = require( '@stdlib/blas/snrm2' );


// TESTS //

// The function returns a number...
{
	snrm2( zeros( [ 10 ] ) ); // $ExpectType float32ndarray
	snrm2( zeros( [ 10 ] ), -1 ); // $ExpectType float32ndarray
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	snrm2( 10 ); // $ExpectError
	snrm2( '10' ); // $ExpectError
	snrm2( true ); // $ExpectError
	snrm2( false ); // $ExpectError
	snrm2( null ); // $ExpectError
	snrm2( undefined ); // $ExpectError
	snrm2( {} ); // $ExpectError
	snrm2( [] ); // $ExpectError
	snrm2( ( x: number ): number => x ); // $ExpectError

	snrm2( 10, -1 ); // $ExpectError
	snrm2( '10', -1 ); // $ExpectError
	snrm2( true, -1 ); // $ExpectError
	snrm2( false, -1 ); // $ExpectError
	snrm2( null, -1 ); // $ExpectError
	snrm2( undefined, -1 ); // $ExpectError
	snrm2( {}, -1 ); // $ExpectError
	snrm2( [], -1 ); // $ExpectError
	snrm2( ( x: number ): number => x, -1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an ndarray...
{
	const x = zeros( [ 10 ] );

	snrm2( x, '10' ); // $ExpectError
	snrm2( x, true ); // $ExpectError
	snrm2( x, false ); // $ExpectError
	snrm2( x, null ); // $ExpectError
	snrm2( x, {} ); // $ExpectError
	snrm2( x, [] ); // $ExpectError
	snrm2( x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = zeros( [ 10 ] );

	snrm2(); // $ExpectError
	snrm2( x, -1, {} ); // $ExpectError
}
